/**
 * Function schema types for RayfinClient (regenerated by the Rayfin CLI from function_app.ts).
 *
 * IMPORTANT: This file must NOT import any Node.js packages; the frontend's TypeScript compiler resolves it.
 */

type Cell = string | number | boolean | null;

export type RequestSummary = {
  QUERY_MASTER_ID: number;
  TITLE: string;
  QUERY_NAME: string;
  NL_QUESTION: string | null;
  STATUS: string;
  PATIENT_COUNT_DISPLAY: string | null;
  REQUESTED_BY: string;
  REQUESTED_AT: string;
  DECIDED_BY: string | null;
  DECIDED_AT: string | null;
  DELIVERED_AT: string | null;
};

export type DeliveryStep = { at: string; event: string; detail: string | null };

export type DeliveryJob = {
  jobId: string;
  runner: string;
  status: string;
  demo: boolean;
  startedBy: string;
  requestedAt: string;
  startTimeUtc: string | null;
  endTimeUtc: string | null;
  failureReason: string | null;
  steps: DeliveryStep[];
  lakehouse: { name: string; url: string | null } | null;
  notebook: { name: string; url: string | null } | null;
  runnerUrl: string;
};

export type RequestDetail = {
  request: Record<string, Cell>;
  definition: string | null;
  breakdown: { BREAKDOWN: string; CATEGORY: string; PATIENTS: number }[];
  events: { EVENT: string; ACTOR: string; EVENT_AT: string; DETAIL: string | null }[];
  delivery: DeliveryJob | null;
  /** Links to what was delivered, however the delivery was started (app, pipeline, notebook or CLI). */
  delivered: { lakehouse: { name: string; url: string | null }; notebook: { name: string; url: string | null } | null } | null;
  /** The cohort's patients in Patient 360, once the request is approved. */
  patient360: string | null;
  viewer: string;
};

/** What the Discovery tab needs to reach the GitHub Copilot relay as the signed-in user. */
export type ChatTicket = { ticket: string; expiresAt: number; chatUrl: string; user: string };

export type AppFunctionsSchema = {
  whoAmI: { input: Record<string, never>; output: string };
  listRequests: { input: Record<string, never>; output: RequestSummary[] };
  getRequest: { input: { queryMasterId: number }; output: RequestDetail };
  decideRequest: { input: { queryMasterId: number; decision: string; comment: string }; output: string };
  startDelivery: { input: { queryMasterId: number; demoMode: boolean }; output: DeliveryJob };
  getDelivery: { input: { queryMasterId: number }; output: DeliveryJob | null };
  discovery: { input: { action: string; payload: string }; output: string };
  chatTicket: { input: Record<string, never>; output: ChatTicket };
};
